def text_to_branches(apps, schema_editor):
    """Guruhlarda matn bilan yozilgan filiallardan Filial yozuvlari yaratiladi."""
    Group = apps.get_model("crm", "Group")
    Branch = apps.get_model("crm", "Branch")
    Student = apps.get_model("crm", "Student")
    for name in sorted({(g.branch or "").strip() for g in Group.objects.all()} - {""}):
        b, _ = Branch.objects.get_or_create(name=name[:100])
        Group.objects.filter(branch=name).update(filial=b)
    for g in Group.objects.exclude(filial=None):
        Student.objects.filter(group=g).update(filial_id=g.filial_id)


